def is_valid_modulus(M):
    """Checks if M is composed only of prime factors q such that q=1 (mod 4),
    or if M = 2 * (product of such primes). M must not be divisible by 4 or 3."""
    if M <= 1:
        return False

    # Must not be divisible by 4
    if M % 4 == 0:
        return False

    temp_M = M
    i = 2
    while i * i <= temp_M:
        if temp_M % i == 0:
            # Must not be divisible by 3
            if i == 3:
                return False

            # Check if prime factor i is 1 mod 4
            if i % 4 != 1 and i != 2:
                # i is an odd prime factor not 1 mod 4 (e.g., 7, 11, 19)
                return False

            while temp_M % i == 0:
                temp_M //= i
        i += 1

    # Check remaining factor
