    # n = x1 + 1
    if n <= 1:
        return True # Trivial or handled by positivity constraint

    factors = get_prime_factors(n)
    for p in factors:
        if p == 2:
            continue
        # For any odd prime factor q, we must have q = 1 mod 4
        if p % 4 != 1:
            return False
    return True

